"""Draw original, topic-specific SVG illustrations for the Shopify guides."""
from pathlib import Path
import json
import html
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'content/article-art'; OUT.mkdir(parents=True,exist_ok=True)
INK='#22221f'; PINK='#ef1f5e'; SOFT='#ffdae4'; PAPER='#fffefa'; GREY='#d4cec4'
def rect(x,y,w,h,fill=PAPER,rx=18,stroke=INK):
 return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" stroke="{stroke}" stroke-width="4"/>'
def path(d,stroke=INK,fill='none',sw=7):
 return f'<path d="{d}" fill="{fill}" stroke="{stroke}" stroke-width="{sw}" stroke-linecap="round" stroke-linejoin="round"/>'
def line(x,y,xx,yy,color=INK,sw=7):return path(f'M{x} {y}L{xx} {yy}',color,sw=sw)
def circle(x,y,r,fill=PAPER,stroke=INK):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}" stroke="{stroke}" stroke-width="4"/>'
def arrow(x,y,xx,yy):
 return line(x,y,xx,yy,PINK)+path(f'M{xx-18} {yy-18}L{xx} {yy}L{xx-18} {yy+18}',PINK)
def check(x,y):return path(f'M{x} {y}l14 14 30-34',PINK,sw=8)
def bars(x,y,width=220,n=3):return ''.join(line(x,y+i*32,x+width-(i%2)*55,y+i*32,GREY,9) for i in range(n))
def browser(x,y,w=350,h=250):return rect(x,y,w,h)+line(x,y+42,x+w,y+42,GREY,3)+''.join(circle(x+18+i*18,y+21,3,PINK,'none') for i in range(3))
def page(x,y,w=250,h=310):return rect(x,y,w,h)+bars(x+28,y+38,w-60,3)
def bag(x,y,s=1):
 return f'<g transform="translate({x} {y}) scale({s})">'+path('M25 60H155L170 205H10Z',INK,SOFT)+path('M55 65V40C55 0 125 0 125 40V65',INK)+check(65,130)+'</g>'
def garment(x,y):return f'<g transform="translate({x} {y})">'+path('M75 10L110 25L180 90L145 125L120 100L145 270H5L30 100L5 125L-30 90L40 25Z',INK,SOFT)+path('M40 25Q75 85 110 25',INK)+line(75,65,75,250,GREY,4)+'</g>'
def card(x,y):return rect(x,y,280,180)+rect(x,y+42,280,38,INK,0,INK)+circle(x+225,y+132,18,SOFT,PINK)+bars(x+28,y+118,100,2)
def box(x,y,w=170):return rect(x,y,w,150,SOFT,8)+line(x+w/2,y,x+w/2,y+150)+line(x,y+45,x+w,y+45)+rect(x+w/2-25,y+70,50,30,PAPER,3,INK)
def globe(x,y):return circle(x,y,125,SOFT)+f'<ellipse cx="{x}" cy="{y}" rx="55" ry="125" fill="none" stroke="{INK}" stroke-width="4"/>'+line(x-125,y,x+125,y)+path(f'M{x-110} {y-60}Q{x} {y-10} {x+110} {y-60}',INK,sw=4)+path(f'M{x-110} {y+60}Q{x} {y+10} {x+110} {y+60}',INK,sw=4)
def frame(content):return browser(170,110,860,450)+content
ART={}
def put(slug,scene,en,ar):ART[slug]=(scene,en,ar)
