from article_art_expansion import add_expansion_art
add_expansion_art(globals())
files=list((ROOT/'content/articles').glob('*.json'))
assert {p.stem for p in files}==set(ART), 'Every article needs its own illustration'
for p in files:
 a=json.loads(p.read_text()); scene,en,ar=ART[a['slug']]
 color={'planning':'#eee9df','catalogue':'#f4e8df','international':'#e8eeeb','operations':'#eee9e1','search':'#e9eaf1','growth':'#f3e6ec','websites':'#e7ecec','platforms':'#eee8f1','qatar':'#efe7df','scaling':'#e5ece8'}[a['category']]
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="675" viewBox="0 0 1200 675" role="img"><title>{html.escape(en)}</title><rect width="1200" height="675" fill="{color}"/><circle cx="1100" cy="80" r="170" fill="#ef1f5e" opacity=".07"/><circle cx="80" cy="640" r="180" fill="#ffffff" opacity=".45"/><text x="64" y="62" fill="{INK}" font-family="Arial,sans-serif" font-size="25" font-weight="700" letter-spacing="2">FIKRA</text><path d="M1090 45h45m-20-20v40" stroke="{PINK}" stroke-width="5" stroke-linecap="round"/>{scene}<path d="M530 620h140" stroke="{PINK}" stroke-width="6" stroke-linecap="round"/></svg>'''
 (OUT/(a['slug']+'.svg')).write_text(svg)
 a['image']={'src':'/assets/article-images/'+a['slug']+'.webp','width':1200,'height':675,'alt':{'en':en,'ar':ar}}
 p.write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n')
print(f'Drawn {len(files)} original article illustrations; source SVGs saved privately')
